const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Antarctic region: south of 60 degrees S latitude.
  const antarctica = ee.Geometry.Rectangle([-180, -90, 180, -60]);

  const start_2002 = '2002-09-01';
  const end_2002 = '2002-09-30';
  const start_2003 = '2003-09-01';
  const end_2003 = '2003-09-30';

  const OZONE_HOLE_THRESHOLD_DU = 220; // Dobson Units

  // Function to get monthly mean ozone and calculate ozone hole area
  const getOzoneHoleArea = async (year, startDate, endDate, region) => {
    const collection = ee.ImageCollection('NASA/TOMS/V8_L3/TO3')
      .filterDate(startDate, endDate)
      .filterBounds(region);

    const size = await collection.size().getInfo();
    if (size === 0) {
      console.log(`No images found for September ${year}.`);
      return null;
    }
    console.log(`September ${year} Images: ${size}`);

    const meanOzone = collection.mean();

    // Check if meanOzone is null (e.g., if collection was empty even after size check, though unlikely)
    if (!meanOzone) {
      console.log(`Mean ozone calculation failed for September ${year}.`);
      return null;
    }

    // Define ozone hole: pixels with ozone less than threshold
    const ozoneHole = meanOzone.select('ozone').lt(OZONE_HOLE_THRESHOLD_DU);

    // Calculate the area of these pixels. Use a relatively coarse scale to avoid memory issues.
    // TOMS resolution is ~1 degree (~111 km at equator). Using 100km scale for area calculation.
    const pixelArea = ee.Image.pixelArea();
    const ozoneHoleAreaImage = ozoneHole.multiply(pixelArea);

    const stats = await ozoneHoleAreaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: 100000, // 100 km scale
      maxPixels: 1e9,
      crs: 'EPSG:4326' // Use WGS84 CRS for consistency with geometry
    }).get('ozone').getInfo();

    if (stats === null) {
      console.log(`Area calculation failed for September ${year}. Result is null.`);
      return null;
    }

    const area_sq_km = stats / 1e6; // Convert m^2 to km^2
    console.log(`September ${year} Ozone Hole Area (sq km): ${area_sq_km.toFixed(2)}`);

    // Check for C2: if the sum is effectively 0 after processing, it's not C2 but a valid result.
    // If stats itself is NaN or infinite, it implies a calculation failure C3.
    if (isNaN(area_sq_km) || !isFinite(area_sq_km)) {
        console.log(`Area calculation resulted in NaN/Infinity for September ${year}.`);
        return null; // This will trigger C3
    }

    return area_sq_km;
  };

  let area_2002;
  let area_2003;

  try {
    area_2002 = await getOzoneHoleArea(2002, start_2002, end_2002, antarctica);
    area_2003 = await getOzoneHoleArea(2003, start_2003, end_2003, antarctica);
  } catch (error) {
    console.log("Error during calculation:", error.message);
    console.log("D"); // General error, could be syntax, memory, etc.
    return;
  }

  // 5. Validation & Final Answer
  if (area_2002 === null || area_2003 === null) {
    if (area_2002 === null && area_2003 === null) {
      console.log("C1"); // Both failed, likely no data
    } else if (area_2002 === null || area_2003 === null) {
      // If one is null, it could be C1 for that year or C3 if calculation failed
      // The function getOzoneHoleArea already prints specific reasons (C1/C3) for null return
      // We'll treat any `null` from `getOzoneHoleArea` as either C1 or C3, as handled within the function.
      // If only one is null, we can't do a comparison.
      if (area_2002 === null) console.log("C3"); // Or C1, as determined inside the function
      else console.log("C3"); // Or C1, as determined inside the function
    }
    return; // Exit after printing C1/C3.
  }

  // Valid zero check: If the calculated area is 0, it means no pixels met the threshold. This is a valid result.
  if (area_2002 === 0 && area_2003 === 0) {
    console.log("Both years had no detected ozone hole based on the threshold.");
  }

  if (area_2003 > area_2002) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
